local function sample(keys,t)
 local key=keys[1];if not key then return 0 end
 for _,k in ipairs(keys)do if k[1]<=t then key=k else break end end
 local dt=math.max(0,t-key[1]);return ((key[2]*dt+key[3])*dt+key[4])*dt+key[5]
end
local function resolve(root,path)
 local n=root
 for part in path:gmatch('[^/]+')do
  local found=nil;for _,c in ipairs(n.children)do if c.name==part then found=c;break end end
  n=found;if not n then return nil end
 end
 return n
end
local function baseValue(n,p)
 local r=n.spec.rect or {}
 if p=='scale' then local v=r.m_LocalScale or {x=1,y=1,z=1};return {v.x,v.y,v.z}
 elseif p=='euler' then
  local q=r.m_LocalRotation or {x=0,y=0,z=0,w=1}
  -- Unity Z-X-Y order. Renderer uses the full quaternion when not animated.
  local x=math.asin(math.max(-1,math.min(1,2*(q.w*q.x-q.y*q.z))))
  return {math.deg(x),math.deg(math.atan(2*(q.w*q.y+q.x*q.z),1-2*(q.x*q.x+q.y*q.y))),math.deg(math.atan(2*(q.w*q.z+q.x*q.y),1-2*(q.x*q.x+q.z*q.z)))}
 elseif p=='m_Alpha' then return {n.spec.alpha or 1}
 elseif p=='m_IsActive' then return {n.spec.active==false and 0 or 1}
 elseif p=='m_FillAmount' then return {n.spec.fill or 1}
 elseif p:sub(1,8)=='m_Color.' then return {(n.spec.color or {r=1,g=1,b=1,a=1})[p:sub(9)]}
 elseif p:sub(1,19)=='m_AnchoredPosition.' then return {(r.m_AnchoredPosition or {x=0,y=0})[p:sub(20)]}
 elseif p:sub(1,16)=='m_LocalPosition.' then return {(r.m_LocalPosition or {x=0,y=0,z=0})[p:sub(17)]}
 elseif p:sub(1,12)=='m_SizeDelta.' then return {(r.m_SizeDelta or {x=0,y=0})[p:sub(13)]} end
end
local function setValue(n,p,v)
 if p=='scale' then n.sx=v[1];n.sy=v[2]
 elseif p=='euler' then n.rx=v[1];n.ry=v[2];n.rz=v[3]
 elseif p=='m_AnchoredPosition.x' then n.x=v[1];n.localX=nil
 elseif p=='m_AnchoredPosition.y' then n.y=v[1];n.localY=nil
 elseif p=='m_LocalPosition.x' then n.localX=v[1]
 elseif p=='m_LocalPosition.y' then n.localY=v[1]
 elseif p=='m_LocalPosition.z' then n.localZ=v[1]
 elseif p=='m_SizeDelta.x' then n.rect.m_SizeDelta.x=v[1]
 elseif p=='m_SizeDelta.y' then n.rect.m_SizeDelta.y=v[1]
 elseif p=='m_IsActive' then n.active=v[1]>0.5
 elseif p=='m_FillAmount' then n.fillAmount=v[1]
 elseif p=='m_Alpha' then n.alpha=v[1]
 elseif p:sub(1,8)=='m_Color.' then n.color=n.color or {r=1,g=1,b=1,a=1};n.color[p:sub(9)]=v[1] end
end
local function pose(clip,t)
 if clip.loop and clip.duration>0 then t=t%clip.duration else t=math.min(t,clip.duration)end
 local out={}
 for _,c in ipairs(clip.curves or {})do
  local v={};for _,keys in ipairs(c.channels)do v[#v+1]=sample(keys,t)end
  out[c.path..'|'..c.property]={path=c.path,property=c.property,value=v}
 end
 return out
end
local function applyAnimations()
 syncActivity()
 for _,root in ipairs(allNodes)do
  if root.clip and active(root) then
   local clip=root.clip;local t=Time.time-(root.animAt or Time.time)
   local tr=root.spec.transitions and root.spec.transitions[root.clipId]
   local values=pose(clip,t)
   if tr and t>=clip.duration*tr.exit then
    local start=clip.duration*tr.exit
    local duration=tr.duration*(tr.fixedDuration==false and clip.duration or 1)
    local weight=duration>0 and math.min(1,(t-start)/duration) or 1
    local dest=SPEC.clips[tr.to];local destTime=t-start+(tr.offset or 0)*dest.duration
    local target=pose(dest,destTime)
    local keys={};for k in pairs(values)do keys[k]=true end;for k in pairs(target)do keys[k]=true end
    for k in pairs(keys)do
     local a,b=values[k],target[k];local c=a or b;local n=resolve(root,c.path)
     if n then
      local av=a and a.value or baseValue(n,c.property);local bv=b and b.value or baseValue(n,c.property)
      if av and bv then
       local v={};for i,x in ipairs(av)do v[i]=x+(bv[i]-x)*weight end
       values[k]={path=c.path,property=c.property,value=v}
      end
     end
    end
    if weight>=1 then root.clipId=tr.to;root.clip=dest;root.animAt=Time.time-destTime end
   end
   for _,c in pairs(values)do local n=resolve(root,c.path);if n then setValue(n,c.property,c.value)end end
  end
 end
 for _,n in ipairs(allNodes)do
  local f=n.spec.fade
  if active(n) and f and f.autoPlay==1 and n.fadeAt then
   local ms=(Time.time-n.fadeAt)*1000
   if ms<f.delay then n.alpha=f.delayValue or 0
   else local t=f.time>0 and math.min(1,(ms-f.delay)/f.time) or 1;n.alpha=f.from+(f.to-f.from)*t end
  end
 end
end
resetAnimated=function(root)
 for _,id in ipairs(root.spec.animatorClips or {})do
  for _,c in ipairs(SPEC.clips[id].curves or {})do
   local n=resolve(root,c.path)
   if n then local v=baseValue(n,c.property);if v then setValue(n,c.property,v)end end
  end
 end
end
syncActivity=function()
 for _,n in ipairs(allNodes)do
  local now=active(n)
  if now and not n.enabled then
   if n.spec.defaultClip then
    if n.spec.keepAnimatorState and n.disabledAt then n.animAt=n.animAt+Time.time-n.disabledAt
    else
     resetAnimated(n);n.clipId=n.spec.defaultClip;n.clip=SPEC.clips[n.clipId];n.animAt=Time.time
    end
   end
   if n.spec.fade then n.fadeAt=Time.time;n.alpha=n.spec.fade.delayValue or 0 end
  elseif not now and n.enabled then n.disabledAt=Time.time end
  n.enabled=now
 end
end
function boot(seed)
 randomState=(math.floor(seed or 1)%4294967296.0)+0.0
 nextRandom();nextRandom()
 roots[#roots+1]=roleNode
 main=instantiate(SPEC.name,nil);main.lua.Refresh(ROLE)
 applyAnimations()
end
function input(id)
 local function find(n)if n.id==id then return n end;for _,c in ipairs(n.children)do local r=find(c);if r then return r end end end
 for _,r in ipairs(roots)do local n=find(r)
  if n and n.handler and active(n) and n.spec.click then
   local now=Time.unscaledTime or Time.time
   if not n.lastClick or now-n.lastClick>=(n.spec.clickInterval or 0) then
    n.lastClick=now
    local count=#commands
    assert(n.handler[n.spec.click],'missing UI callback')()
    emit({type='input-trace',node=id,callback=n.spec.click,time=Time.time,unscaledTime=now,
     outcome=#commands>count and 'callback-with-commands' or 'callback-without-commands'})
   else emit({type='input-trace',node=id,time=Time.time,unscaledTime=now,outcome='button-cooldown'})end
   return
  end
 end
 emit({type='input-trace',node=id,time=Time.time,outcome='inactive-or-missing'})
end
function advance(dt,isIdle,done,events)
 if isIdle~=nil then idle=isIdle end
 for _,token in ipairs(done or {})do local cb=callbacks[token];callbacks[token]=nil;if cb then cb()end end
 for _,id in ipairs(events or {})do input(id)end
 remainder=remainder+dt
 local steps=math.floor(remainder*60+1e-8);local delta=1/60
 remainder=remainder-steps*delta
 for i=1,steps do
  Time.deltaTime=delta;Time.time=Time.time+delta
  for j=#tasks,1,-1 do if tasks[j].at<=Time.time then local t=table.remove(tasks,j);t.fn()end end
  local count=#instances
  for j=1,count do local it=instances[j];if active(it.node) and it.env.Update then it.env.Update()end end
  applyAnimations()
 end
end
local function quote(s)return '"'..tostring(s):gsub('\\','\\\\'):gsub('"','\\"'):gsub('\n','\\n'):gsub('\r','\\r'):gsub('\t','\\t')..'"'end
local function json(v)
 local k=type(v)
 if k=='nil' then return 'null' elseif k=='boolean' or k=='number' then return tostring(v) elseif k=='string' then return quote(v) end
 local a={}
 if #v>0 then for _,x in ipairs(v)do a[#a+1]=json(x)end;return '['..table.concat(a,',')..']' end
 for key,x in pairs(v)do a[#a+1]=quote(key)..':'..json(x)end;return '{'..table.concat(a,',')..'}'
end
local function fullNode(n,parentId)
 local d=n.spec
 return {id=n.id,parent=parentId,name=n.name,active=n.active and n.animVisible~=false,
  x=n.x,y=n.y,localX=n.localX,localY=n.localY,localZ=n.localZ,sx=n.sx,sy=n.sy,rx=n.rx,ry=n.ry,rz=n.rz,rect=n.rect,image=n.image,text=n.text,fontSize=d.fontSize,
  fill=n.fillAmount,filled=d.filled,fillMethod=d.fillMethod,fillOrigin=d.fillOrigin,color=n.color,
  imageMeta=SPEC.imageMetadata and SPEC.imageMetadata[n.image],imageType=d.imageType,material=d.material,
  preserveAspect=d.preserveAspect,fillClockwise=d.fillClockwise,fillCenter=d.fillCenter,ppuMultiplier=d.ppuMultiplier,
  mask=d.mask,rectMask=d.rectMask,fitter=d.fitter,
  click=d.click,layout=d.layout,alpha=n.alpha,anim=n.anim,animElapsed=n.animAt and Time.time-n.animAt or nil}
end
function snapshot()
 local out={}
 local function scan(n,parentId)
  if n.dead then return end
  out[#out+1]=fullNode(n,parentId)
  for _,c in ipairs(n.children)do scan(c,n.id)end
 end
 for _,r in ipairs(roots)do scan(r,nil)end
 local result=json({nodes=out,commands=commands,time=Time.time});commands={};return result
end
-- Browser runtime uses one full snapshot at boot, then only changed node
-- properties. The canonical full snapshot above remains for native/xLua checks.
local previousDelta={}
function snapshotDelta()
 local changed={}
 local current={}
 for _,n in ipairs(allNodes)do
  if not n.dead then
   current[n.id]=true
   local r=n.rect or {};local size=r.m_SizeDelta or {};local color=n.color or {}
   local parentId=n.parent and n.parent.id
   local visible=n.active and n.animVisible~=false
   local old=previousDelta[n.id]
   -- Keep the previous primitive state for unchanged nodes. Allocating a new
   -- 24-field table for every prefab node on every frame causes GC spikes on phones.
   local dirty=not old or visible~=old[1] or n.x~=old[2] or n.y~=old[3]
    or n.localX~=old[4] or n.localY~=old[5] or n.localZ~=old[6]
    or n.sx~=old[7] or n.sy~=old[8] or n.rx~=old[9] or n.ry~=old[10] or n.rz~=old[11]
    or n.image~=old[12] or n.text~=old[13] or n.fillAmount~=old[14]
    or n.alpha~=old[15] or n.anim~=old[16] or n.animAt~=old[17]
    or size.x~=old[18] or size.y~=old[19]
    or color.r~=old[20] or color.g~=old[21] or color.b~=old[22] or color.a~=old[23]
    or parentId~=old[24]
   if dirty then
    local state={visible,n.x,n.y,n.localX,n.localY,n.localZ,
     n.sx,n.sy,n.rx,n.ry,n.rz,n.image,n.text,n.fillAmount,n.alpha,
     n.anim,n.animAt,size.x,size.y,color.r,color.g,color.b,color.a,parentId}
    if not old then
     changed[#changed+1]=fullNode(n,parentId)
    else
    -- Most rhythm frames only move a few notes. Sending every property (including
    -- rect and color) for each moving note makes Lua JSON encoding expensive.
    local patch={id=n.id}
    if state[1]~=old[1] then patch.active=state[1] end
    if state[2]~=old[2] then patch.x=n.x end
    if state[3]~=old[3] then patch.y=n.y end
    if state[4]~=old[4] then patch.localX=n.localX or false end
    if state[5]~=old[5] then patch.localY=n.localY or false end
    if state[6]~=old[6] then patch.localZ=n.localZ or false end
    if state[7]~=old[7] then patch.sx=n.sx end
    if state[8]~=old[8] then patch.sy=n.sy end
    if state[9]~=old[9] then patch.rx=n.rx end
    if state[10]~=old[10] then patch.ry=n.ry end
    if state[11]~=old[11] then patch.rz=n.rz end
    if state[12]~=old[12] then patch.image=n.image or false end
    if state[13]~=old[13] then patch.text=n.text or false end
    if state[14]~=old[14] then patch.fill=n.fillAmount or 1 end
    if state[15]~=old[15] then patch.alpha=n.alpha or 1 end
    if state[16]~=old[16] then patch.anim=n.anim or false end
    if state[17]~=old[17] or n.animAt then patch.animElapsed=n.animAt and Time.time-n.animAt or false end
    if state[18]~=old[18] or state[19]~=old[19] then patch.rect=r end
    if state[20]~=old[20] or state[21]~=old[21] or state[22]~=old[22] or state[23]~=old[23] then patch.color=n.color end
    if state[24]~=old[24] then patch.parent=state[24] or false end
     changed[#changed+1]=patch
    end
    previousDelta[n.id]=state
   end
  end
 end
 local removed={}
 for id in pairs(previousDelta)do if not current[id] then removed[#removed+1]=id;previousDelta[id]=nil end end
 local result=json({nodes=changed,removed=removed,commands=commands,time=Time.time});commands={};return result
end
function shutdown()
 for _,i in ipairs(instances)do if i.env.OnDestroy then i.env.OnDestroy()end end
 return snapshot()
end
